void TreeNode::preOrder(int level)
{
	for (int i = 0; i < level; i++)
		std::cout << "    ";
	if (type == "LEAF")
		std::cout << info << std::endl;          // leaf: relation name only
	else if (info.empty())
		std::cout << type << std::endl;          // JOIN: no predicate/attr list
	else
		std::cout << type << " [ " << info << " ]" << std::endl;

	if (left != NULL)
		left->preOrder(level + 1);
	if (right != NULL)
		right->preOrder(level + 1);
}

#include <iostream>
#include <string>
#include <vector>
#include "tree.h"

using namespace std;

void parseQuery(TreeNode *root, string query);
TreeNode *optimizeQuery(TreeNode *root, vector<string> info);

int main()
{
	string query1 = "SELECT [ ENAME = 'Mary' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT )";
	string query2 = "PROJECTION [ BDATE ] ( SELECT [ ENAME = 'John' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT ) )";
	string query3 = "SELECT [ ESSN = '01' ] ( PROJECTION [ ESSN, PNAME ] ( WORKS_ON JOIN PROJECT ) )";
	string query[3] = { query1, query2, query3 };

	for (int i = 0; i < 3; i++) {
		cout << "Query " << i + 1 << ":" << endl << endl;
		TreeNode *root = new TreeNode(); // root node does not store any information
		parseQuery(root, query[i]);
		root->left->preOrder(0);
		cout << endl;
		root->left = optimizeQuery(root->left, vector<string>());
		root->left->preOrder(0);
		cout << endl;
	}

	return 0;
}

/* ------------------------------------------------------------------ helpers */

static string trim(const string &s)
{
	size_t b = s.find_first_not_of(" \t\r\n");
	if (b == string::npos)
		return "";
	size_t e = s.find_last_not_of(" \t\r\n");
	return s.substr(b, e - b + 1);
}

// index of the ')' matching the '(' at position open
static size_t matchParen(const string &s, size_t open)
{
	int depth = 0;
	for (size_t i = open; i < s.size(); i++) {
		if (s[i] == '(')
			depth++;
		else if (s[i] == ')' && --depth == 0)
			return i;
	}
	return string::npos;
}

// split "A = 'x' & B = 'y'" into individual, trimmed predicates
static vector<string> splitPredicates(const string &pred)
{
	vector<string> out;
	size_t start = 0;
	while (true) {
		size_t amp = pred.find('&', start);
		string one = trim(amp == string::npos ? pred.substr(start)
		                                     : pred.substr(start, amp - start));
		if (!one.empty())
			out.push_back(one);
		if (amp == string::npos)
			break;
		start = amp + 1;
	}
	return out;
}

// leading attribute name of a predicate: "ENAME = 'Mary'" -> "ENAME"
static string predAttr(const string &pred)
{
	size_t e = pred.find_first_of(" \t=<>!");
	return e == string::npos ? pred : pred.substr(0, e);
}

/* ------------------------------------------------------------- parseQuery */

static TreeNode *parseExpr(string s)
{
	s = trim(s);
	// strip a redundant pair of parentheses wrapping the whole expression
	while (s.size() >= 2 && s[0] == '(' && matchParen(s, 0) == s.size() - 1)
		s = trim(s.substr(1, s.size() - 2));

	if (s.compare(0, 6, "SELECT") == 0 || s.compare(0, 10, "PROJECTION") == 0) {
		string type = (s[0] == 'S') ? "SELECT" : "PROJECTION";
		size_t lb = s.find('[');
		size_t rb = s.find(']', lb);
		TreeNode *node = new TreeNode(type, trim(s.substr(lb + 1, rb - lb - 1)));
		size_t lp = s.find('(', rb);
		node->left = parseExpr(s.substr(lp + 1, matchParen(s, lp) - lp - 1));
		return node;
	}

	// top-level JOIN?
	int depth = 0;
	for (size_t i = 0; i < s.size(); i++) {
		if (s[i] == '(' || s[i] == '[')
			depth++;
		else if (s[i] == ')' || s[i] == ']')
			depth--;
		else if (depth == 0 && s.compare(i, 4, "JOIN") == 0) {
			TreeNode *node = new TreeNode("JOIN");
			node->left = parseExpr(s.substr(0, i));
			node->right = parseExpr(s.substr(i + 4));
			return node;
		}
	}
	return new TreeNode("LEAF", s);           // relation name
}

void parseQuery(TreeNode *root, string query)
{
	root->left = parseExpr(query);            // main() reads the tree from root->left
}

/* ----------------------------------------------------------- optimizeQuery */

// which relation owns an attribute (simplified COMPANY catalogue)
static bool relationHasAttr(const string &rel, const string &attr)
{
	static const char *cat[][12] = {
		{ "EMPLOYEE",   "ENAME", "FNAME", "MINIT", "LNAME", "SSN", "BDATE",
		  "ADDRESS", "SEX", "SALARY", "SUPERSSN", "DNO" },
		{ "DEPARTMENT", "DNAME", "DNUMBER", "MGRSSN", "MGRSTARTDATE", 0 },
		{ "DEPT_LOCATIONS", "DNUMBER", "DLOCATION", 0 },
		{ "PROJECT",    "PNAME", "PNUMBER", "PLOCATION", "DNUM", 0 },
		{ "WORKS_ON",   "ESSN", "PNO", "HOURS", 0 },
		{ "DEPENDENT",  "ESSN", "DEPENDENT_NAME", "RELATIONSHIP", 0 },
		{ 0 }
	};
	for (int r = 0; cat[r][0]; r++) {
		if (rel != cat[r][0])
			continue;
		for (int a = 1; a < 12 && cat[r][a]; a++)
			if (attr == cat[r][a])
				return true;
	}
	return false;
}

static void collectRelations(TreeNode *n, vector<string> &out)
{
	if (n == NULL)
		return;
	if (n->type == "LEAF")
		out.push_back(n->info);
	collectRelations(n->left, out);
	collectRelations(n->right, out);
}

// tier 1 catalogue, tier 2 shared-prefix heuristic
static int subtreeScore(TreeNode *n, const string &attr)
{
	vector<string> rels;
	collectRelations(n, rels);
	int best = 0;
	for (size_t i = 0; i < rels.size(); i++) {
		if (relationHasAttr(rels[i], attr)) {
			best = 100;
		} else {
			size_t k = 0;
			while (k < rels[i].size() && k < attr.size() && rels[i][k] == attr[k])
				k++;
			if ((int)k > best)
				best = (int)k;
		}
	}
	return best;
}

static bool projectionKeeps(const string &attrList, const string &attr)
{
	vector<string> items;
	size_t start = 0;
	while (true) {
		size_t c = attrList.find(',', start);
		string one = trim(c == string::npos ? attrList.substr(start)
		                                   : attrList.substr(start, c - start));
		if (one == attr || one == "*")
			return true;
		if (c == string::npos)
			return false;
		start = c + 1;
	}
}

// stack pending SELECT nodes on top of `node`, first predicate outermost
static TreeNode *stackSelects(TreeNode *node, const vector<string> &preds)
{
	for (int i = (int)preds.size() - 1; i >= 0; i--) {
		TreeNode *sel = new TreeNode("SELECT", preds[i]);
		sel->left = node;
		node = sel;
	}
	return node;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL)
		return NULL;

	if (root->type == "SELECT") {
		// (1) break the conjunction up and carry the parts downwards
		vector<string> parts = splitPredicates(root->info);
		info.insert(info.end(), parts.begin(), parts.end());
		return optimizeQuery(root->left, info);
	}

	if (root->type == "PROJECTION") {
		// (2) a predicate may sink below the projection only if the
		//     projection still keeps the attribute it tests
		vector<string> down, stay;
		for (size_t i = 0; i < info.size(); i++) {
			if (projectionKeeps(root->info, predAttr(info[i])))
				down.push_back(info[i]);
			else
				stay.push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, down);
		return stackSelects(root, stay);
	}

	if (root->type == "JOIN") {
		// (3) route each predicate to the branch that owns its attribute
		vector<string> goLeft, goRight, stay;
		for (size_t i = 0; i < info.size(); i++) {
			string attr = predAttr(info[i]);
			int l = subtreeScore(root->left, attr);
			int r = subtreeScore(root->right, attr);
			if (l > r)
				goLeft.push_back(info[i]);
			else if (r > l)
				goRight.push_back(info[i]);
			else if (l > 0)
				goLeft.push_back(info[i]);   // tie, both plausible
			else
				stay.push_back(info[i]);     // owner unknown: keep above JOIN
		}
		root->left = optimizeQuery(root->left, goLeft);
		root->right = optimizeQuery(root->right, goRight);
		return stackSelects(root, stay);
	}

	// LEAF: everything that reached here filters this relation
	return stackSelects(root, info);
}
